CREATE DATABASE IF NOT EXISTS nexus CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nexus;
CREATE TABLE usuarios (id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(150) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,telefone VARCHAR(25) NULL,cpf VARCHAR(14) UNIQUE NOT NULL,senha_hash VARCHAR(255) NOT NULL,perfil ENUM('ADMIN','ASSOCIADO') NOT NULL DEFAULT 'ASSOCIADO',status_financeiro ENUM('EM_DIA','DEVEDOR','DESFILIADO') NOT NULL DEFAULT 'EM_DIA',matricula VARCHAR(40) UNIQUE NOT NULL,data_filiacao DATE NOT NULL,foto VARCHAR(255) NULL,qr_version INT NOT NULL DEFAULT 1,qr_valid_until DATE NULL,primeiro_acesso TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE mensalidades (id INT AUTO_INCREMENT PRIMARY KEY,associado_id INT NOT NULL,mes_referencia TINYINT NOT NULL,ano_referencia SMALLINT NOT NULL,valor DECIMAL(10,2) NOT NULL,data_vencimento DATE NOT NULL,data_pagamento DATE NULL,forma_pagamento VARCHAR(40),status_pagamento ENUM('PAGO','PENDENTE','CANCELADO') DEFAULT 'PENDENTE',origem ENUM('MANUAL','ECONSIG','SEPLAG') DEFAULT 'MANUAL',UNIQUE KEY competencia(associado_id,mes_referencia,ano_referencia),FOREIGN KEY(associado_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id INT NULL,acao VARCHAR(80) NOT NULL,tabela VARCHAR(80),registro_id INT,dados_antigos_json JSON,dados_novos_json JSON,ip_origem VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL);
CREATE TABLE login_attempts (id BIGINT AUTO_INCREMENT PRIMARY KEY,identifier_hash CHAR(64) NOT NULL,ip_hash CHAR(64) NOT NULL,attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_login(identifier_hash,ip_hash,attempted_at));
-- O primeiro administrador deve ser criado pelo instalador seguro, nunca por senha padrão no schema.
